mapper.select:
SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_resource_element
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND element_type = #{elementType}
  AND element_id = #{elementId}

mapper.update:
UPDATE bt_resource_element
